class BaseMetadataService {
  constructor(serviceName) {
    this.serviceName = serviceName;
  }

  /**
   * Run the metadata extraction process.
   * 
   * @param {Function} onProgress - Callback function to report real-time status and progress: (stage, message, details)
   * @returns {Promise<object>} Summary statistics of the extraction
   */
  async extract(onProgress) {
    throw new Error(`extract method must be implemented for ${this.serviceName}`);
  }
}

module.exports = BaseMetadataService;
