const path = require('path');
const fs = require('fs-extra');

const IS_WINDOWS = process.platform === 'win32';

/**
 * Resolves a path to an absolute form suitable for membership checks. On
 * Windows (case-insensitive filesystem) the result is lower-cased so that a
 * file written as `Accounts/...` still matches an on-disk entry read back as
 * `accounts/...`. Both the "written" set and the sweep must use this function.
 * @param {string} p - The path to normalize.
 * @returns {string} Normalized absolute path key.
 */
function normalizePath(p) {
  const resolved = path.resolve(p);
  return IS_WINDOWS ? resolved.toLowerCase() : resolved;
}

/**
 * Lower-cases a directory/name key on Windows for case-insensitive comparison.
 * @param {string} name
 * @returns {string}
 */
function normalizeName(name) {
  return IS_WINDOWS ? String(name).toLowerCase() : String(name);
}

/**
 * Recursively removes files inside `dir` that are NOT present in `writtenSet`
 * (resolved absolute paths written during this run), then prunes any directory
 * left empty. Used to delete local metadata that no longer exists on Zoho CRM.
 *
 * @param {string} dir - Directory to reconcile.
 * @param {Set<string>} writtenSet - Absolute paths written this run (to keep).
 * @returns {Promise<number>} Count of files removed.
 */
async function sweepDir(dir, writtenSet) {
  let removed = 0;
  if (!(await fs.pathExists(dir))) return 0;

  const entries = await fs.readdir(dir);
  for (const entry of entries) {
    const full = path.join(dir, entry);
    let stat;
    try {
      stat = await fs.stat(full);
    } catch (statErr) {
      continue;
    }

    if (stat.isDirectory()) {
      removed += await sweepDir(full, writtenSet);
      try {
        const remaining = await fs.readdir(full);
        if (remaining.length === 0) await fs.remove(full);
      } catch (pruneErr) {
        // ignore prune failures
      }
    } else if (!writtenSet.has(normalizePath(full))) {
      try {
        await fs.remove(full);
        removed++;
      } catch (rmErr) {
        // ignore individual delete failures
      }
    }
  }
  return removed;
}

/**
 * Removes immediate sub-directories of `parentDir` whose name is not in
 * `validNames` (e.g. module folders for modules deleted on Zoho CRM).
 *
 * @param {string} parentDir - Parent directory (e.g. crm/meta/modules).
 * @param {Set<string>} validNames - Directory names that should be kept.
 * @returns {Promise<number>} Count of directories removed.
 */
async function sweepDeletedDirs(parentDir, validNames) {
  let removed = 0;
  if (!(await fs.pathExists(parentDir))) return 0;

  // Normalize the valid-name set for case-insensitive comparison on Windows.
  const validNormalized = new Set([...validNames].map(normalizeName));

  const entries = await fs.readdir(parentDir);
  for (const entry of entries) {
    const full = path.join(parentDir, entry);
    let stat;
    try {
      stat = await fs.stat(full);
    } catch (statErr) {
      continue;
    }
    if (stat.isDirectory() && !validNormalized.has(normalizeName(entry))) {
      try {
        await fs.remove(full);
        removed++;
      } catch (rmErr) {
        // ignore
      }
    }
  }
  return removed;
}

module.exports = { sweepDir, sweepDeletedDirs, normalizePath };
