const fs = require('fs-extra');
const path = require('path');
const axios = require('axios');
const { logError, logInfo } = require('../utils/logger');
const configStore = require('../utils/configStore');

const TOKENS_PATH = path.join(process.cwd(), 'storage/auth/tokens.json');

/**
 * Handles Zoho CRM OAuth2 authentication flow and token maintenance.
 *
 * Dependency seams (added for host reuse, e.g. the VS Code extension):
 *   - `credentials`: optional provider exposing getClientId/getClientSecret/
 *     getRedirectUri/getScopes/getDc. When present, it overrides the
 *     env/configStore lookups. Partial providers fall back per-getter.
 *   - `store`: optional async token store exposing loadTokens()/saveTokens(t).
 *     When present, the constructor does NOT auto-hydrate (SecretStorage is
 *     async) — the caller must `await hydrate()` once after construction.
 *   - `logger`: optional { logInfo, logError } sink (e.g. an OutputChannel).
 *   - `http`: optional axios-like client (defaults to axios).
 *
 * With NO deps the behaviour is identical to the original CLI/web singleton,
 * so existing callers are unaffected.
 */
class AuthService {
  /**
   * @param {{credentials?:object, store?:object, logger?:object, http?:object}} [deps]
   */
  constructor(deps = {}) {
    /** @type {object|null} */
    this.credentials = deps.credentials || null;
    /** @type {object|null} */
    this.store = deps.store || null;
    /** @type {{logInfo:Function, logError:Function}} */
    this.log = deps.logger || { logInfo, logError };
    /** @type {object} */
    this.http = deps.http || axios;
    /** @type {Promise<string>|null} in-flight refresh (single-flight mutex) */
    this._refreshPromise = null;
    /** @type {object|null} */
    this.tokens = null;

    // Legacy/CLI path hydrates synchronously at construction. When an async
    // `store` is injected, defer to hydrate() (SecretStorage cannot be read
    // synchronously) so we never touch process.cwd() or block the host.
    if (!this.store) {
      this.loadTokens();
    }
  }

  /**
   * Inject/override dependency ports on an existing instance (e.g. the exported
   * singleton, which `apiClient` already shares). After configuring with a
   * `store`, call `await hydrate()` to load tokens.
   * @param {{credentials?:object, store?:object, logger?:object, http?:object}} deps
   * @returns {AuthService} this
   */
  configure(deps = {}) {
    if (deps.credentials !== undefined) this.credentials = deps.credentials;
    if (deps.store !== undefined) this.store = deps.store;
    if (deps.logger !== undefined) this.log = deps.logger;
    if (deps.http !== undefined) this.http = deps.http;
    return this;
  }

  /**
   * Asynchronously hydrate the in-memory tokens from the injected store (or the
   * legacy sync source when no store is configured). Call once after
   * construction/configure when using an async store.
   * @returns {Promise<object|null>} the loaded tokens
   */
  async hydrate() {
    if (this.store && typeof this.store.loadTokens === 'function') {
      try {
        this.tokens = (await this.store.loadTokens()) || null;
      } catch (error) {
        this.log.logError(error, 'AuthService.hydrate');
        this.tokens = null;
      }
    } else {
      this.loadTokens();
    }
    return this.tokens;
  }

  /**
   * Retrieves the current Client ID based on running environment.
   * @returns {string} The Client ID.
   */
  getClientId() {
    if (this.credentials && this.credentials.getClientId) {
      const v = this.credentials.getClientId();
      if (v) return v;
    }
    if (process.env.ZCRM_CLI_MODE === 'true') {
      return configStore.get('client_id') || process.env.ZOHO_CLIENT_ID;
    }
    return process.env.ZOHO_CLIENT_ID;
  }

  /**
   * Retrieves the current Client Secret based on running environment.
   * @returns {string} The Client Secret.
   */
  getClientSecret() {
    if (this.credentials && this.credentials.getClientSecret) {
      const v = this.credentials.getClientSecret();
      if (v) return v;
    }
    if (process.env.ZCRM_CLI_MODE === 'true') {
      return configStore.get('client_secret') || process.env.ZOHO_CLIENT_SECRET;
    }
    return process.env.ZOHO_CLIENT_SECRET;
  }

  /**
   * Retrieves the current Redirect URI based on running environment.
   * @returns {string} The Redirect URI.
   */
  getRedirectUri() {
    if (this.credentials && this.credentials.getRedirectUri) {
      const v = this.credentials.getRedirectUri();
      if (v) return v;
    }
    if (process.env.ZCRM_CLI_MODE === 'true') {
      return configStore.get('redirect_uri') || process.env.ZOHO_REDIRECT_URI;
    }
    return process.env.ZOHO_REDIRECT_URI;
  }

  /**
   * Retrieves the authorization scopes.
   * @returns {string} Commas-separated list of scopes.
   */
  getScopes() {
    if (this.credentials && this.credentials.getScopes) {
      const v = this.credentials.getScopes();
      if (v) return v;
    }
    // Every scope below is a documented ZohoCRM V8 scope. Audit logs have NO
    // `.ALL` variant — the export flow uses the specific operation scopes
    // (CREATE to initiate, READ to poll). send_mail likewise has no `.ALL`
    // token-wide variant — `send_mail.all.CREATE` is the documented form
    // (`all` = all supported modules) and powers `zcrm mail send`. The download
    // step's cross-service ZohoFiles scope is intentionally NOT requested here
    // so a single login stays entirely within ZohoCRM scopes (it can be added
    // via ZOHO_SCOPES if a particular account needs it for the audit download).
    // composite_requests.CUSTOM powers `zcrm composite`; ZohoSearch.securesearch.READ
    // is required by `record search`; ZohoFiles.files.ALL is required by the
    // bulk-write upload step and the audit/bulk result downloads. Existing
    // logins keep their old grant — re-run `zcrm login` to pick these up.
    const defaultScopes = 'ZohoCRM.modules.ALL,ZohoCRM.settings.ALL,ZohoCRM.users.ALL,ZohoCRM.org.ALL,ZohoCRM.bulk.ALL,ZohoCRM.notifications.ALL,ZohoCRM.coql.READ,ZohoCRM.settings.functions.ALL,ZohoCRM.settings.audit_logs.CREATE,ZohoCRM.settings.audit_logs.READ,ZohoCRM.send_mail.all.CREATE,ZohoCRM.composite_requests.CUSTOM,ZohoSearch.securesearch.READ,ZohoFiles.files.ALL';
    if (process.env.ZCRM_CLI_MODE === 'true') {
      return configStore.get('scopes') || process.env.ZOHO_SCOPES || defaultScopes;
    }
    return process.env.ZOHO_SCOPES || defaultScopes;
  }

  /**
   * Retrieves the Zoho Data Center domain extension (e.g. 'com', 'eu').
   * @returns {string} DC extension.
   */
  getDc() {
    if (this.credentials && this.credentials.getDc) {
      const v = this.credentials.getDc();
      if (v) return v;
    }
    if (process.env.ZCRM_CLI_MODE === 'true') {
      return configStore.get('dc') || process.env.ZOHO_DC || 'com';
    }
    return process.env.ZOHO_DC || 'com';
  }

  /**
   * Load tokens from the injected store (sync variant), config store, or local
   * storage file. Async stores (SecretStorage) are handled by hydrate().
   * @returns {void}
   */
  loadTokens() {
    try {
      if (this.store && typeof this.store.loadTokensSync === 'function') {
        this.tokens = this.store.loadTokensSync() || null;
        return;
      }
      if (process.env.ZCRM_CLI_MODE === 'true') {
        this.tokens = configStore.get('tokens') || null;
      } else {
        if (fs.existsSync(TOKENS_PATH)) {
          this.tokens = fs.readJsonSync(TOKENS_PATH);
        }
      }
    } catch (error) {
      this.log.logError(error, 'AuthService.loadTokens');
      this.tokens = null;
    }
  }

  /**
   * Save tokens to the injected store, config store, or local storage file.
   * @param {object} tokensData - The Zoho token response payload.
   * @returns {Promise<void>}
   */
  async saveTokens(tokensData) {
    try {
      const now = Date.now();
      const expires_in = tokensData.expires_in || 3600;
      const currentTokens = this.tokens || {};

      this.tokens = {
        access_token: tokensData.access_token,
        refresh_token: tokensData.refresh_token || currentTokens.refresh_token,
        api_domain: tokensData.api_domain || currentTokens.api_domain || `https://www.zohoapis.${this.getDc()}`,
        expires_in: expires_in,
        expiry_time: now + (expires_in * 1000)
      };

      if (this.store && typeof this.store.saveTokens === 'function') {
        await this.store.saveTokens(this.tokens);
      } else if (process.env.ZCRM_CLI_MODE === 'true') {
        configStore.save({ tokens: this.tokens });
      } else {
        await fs.ensureDir(path.dirname(TOKENS_PATH));
        await fs.writeJson(TOKENS_PATH, this.tokens, { spaces: 2 });
      }
      this.log.logInfo('Tokens saved successfully.', 'AuthService.saveTokens');
    } catch (error) {
      this.log.logError(error, 'AuthService.saveTokens');
      throw error;
    }
  }

  /**
   * Get Zoho accounts domain based on configured DC.
   * @returns {string} Zoho Accounts base URL.
   */
  getAccountsDomain() {
    const dc = this.getDc();
    return `https://accounts.zoho.${dc}`;
  }

  /**
   * Generate authorization URL for Zoho login.
   * @returns {string} The full OAuth redirect URL.
   */
  getAuthorizationUrl() {
    const clientId = this.getClientId();
    const redirectUri = this.getRedirectUri();
    const scope = this.getScopes();
    const accountsDomain = this.getAccountsDomain();

    // prompt=consent ensures refresh_token is always generated on oauth flow
    return `${accountsDomain}/oauth/v2/auth?response_type=code&client_id=${clientId}&redirect_uri=${encodeURIComponent(redirectUri)}&scope=${encodeURIComponent(scope)}&access_type=offline&prompt=consent`;
  }

  /**
   * Exchange the authorization code for access and refresh tokens.
   * @param {string} code - The temporary authorization code.
   * @returns {Promise<object>} The loaded tokens.
   */
  async handleCallback(code) {
    try {
      const accountsDomain = this.getAccountsDomain();
      const params = new URLSearchParams({
        grant_type: 'authorization_code',
        client_id: this.getClientId(),
        client_secret: this.getClientSecret(),
        redirect_uri: this.getRedirectUri(),
        code: code
      });

      this.log.logInfo(`Exchanging authorization code on: ${accountsDomain}/oauth/v2/token`, 'AuthService.handleCallback');
      const response = await this.http.post(`${accountsDomain}/oauth/v2/token`, params.toString(), {
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded'
        }
      });

      if (response.data.error) {
        throw new Error(`Zoho OAuth Error: ${response.data.error}`);
      }

      await this.saveTokens(response.data);
      return this.tokens;
    } catch (error) {
      this.log.logError(error.response?.data || error, 'AuthService.handleCallback');
      throw error;
    }
  }

  /**
   * Refreshes the in-memory tokens from their backing store. In CLI mode this
   * re-reads the global config (which another process — e.g. `zcrm login` — may
   * have updated); in web mode it re-reads the local tokens file. With an
   * injected async store this is a no-op (use hydrate() instead). Call before
   * authentication checks in the long-running web server so they never act on a
   * stale snapshot loaded at process start.
   * @returns {void}
   */
  syncTokens() {
    if (this.store) {
      // Injected async store: hydration is async; callers should use hydrate().
      return;
    }
    if (process.env.ZCRM_CLI_MODE === 'true') {
      configStore.reload();
    }
    this.loadTokens();
  }

  /**
   * Check if tokens are loaded and valid.
   * @returns {boolean} Whether user is authenticated.
   */
  isAuthenticated() {
    return !!(this.tokens && (this.tokens.access_token || this.tokens.refresh_token));
  }

  /**
   * Check if the access token has expired or is about to expire (1 minute buffer).
   * @returns {boolean} Whether the access token is expired.
   */
  isAccessTokenExpired() {
    if (!this.tokens || !this.tokens.expiry_time) return true;
    return Date.now() >= (this.tokens.expiry_time - 60000);
  }

  /**
   * Refresh the access token using the stored refresh token. Single-flight: if a
   * refresh is already in progress, concurrent callers await the same request
   * instead of issuing duplicate refreshes (which waste calls and can trip
   * Zoho's per-minute refresh throttle).
   * @returns {Promise<string>} The new access token.
   */
  async refreshAccessToken() {
    if (this._refreshPromise) {
      return this._refreshPromise;
    }
    this._refreshPromise = this._doRefresh().finally(() => {
      this._refreshPromise = null;
    });
    return this._refreshPromise;
  }

  /**
   * Performs the actual token-refresh request. Always go through
   * refreshAccessToken() so the single-flight mutex applies.
   * @returns {Promise<string>} The new access token.
   * @private
   */
  async _doRefresh() {
    if (!this.tokens || !this.tokens.refresh_token) {
      throw new Error('No refresh token available. Re-authentication required.');
    }

    try {
      const accountsDomain = this.getAccountsDomain();
      const params = new URLSearchParams({
        grant_type: 'refresh_token',
        client_id: this.getClientId(),
        client_secret: this.getClientSecret(),
        refresh_token: this.tokens.refresh_token
      });

      this.log.logInfo('Refreshing expired access token...', 'AuthService.refreshAccessToken');
      const response = await this.http.post(`${accountsDomain}/oauth/v2/token`, params.toString(), {
        headers: {
          'Content-Type': 'application/x-www-form-urlencoded'
        }
      });

      if (response.data.error) {
        throw new Error(`Zoho OAuth Token Refresh Error: ${response.data.error}`);
      }

      await this.saveTokens(response.data);
      this.log.logInfo('Token refresh successful.', 'AuthService.refreshAccessToken');
      return this.tokens.access_token;
    } catch (error) {
      this.log.logError(error.response?.data || error, 'AuthService.refreshAccessToken');
      throw error;
    }
  }

  /**
   * Retrieve the current active access token, refreshing if expired.
   * @returns {Promise<string>} Resolves to a valid access token.
   */
  async getAccessToken() {
    // CLI mode: re-read tokens from the global config in case another process
    // updated them. With an injected store we hydrate once and refresh via the
    // single-flight mutex, so skip the per-call disk re-read.
    if (!this.store && process.env.ZCRM_CLI_MODE === 'true') {
      configStore.reload();
      this.loadTokens();
    }

    if (!this.isAuthenticated()) {
      throw new Error('Not authenticated. Please login first.');
    }

    if (this.isAccessTokenExpired()) {
      await this.refreshAccessToken();
    }

    return this.tokens.access_token;
  }

  /**
   * Best-effort revoke of the current refresh token at Zoho, then forget the
   * in-memory tokens. Used by the extension's logout. Never throws — the caller
   * clears local/secret state regardless of the network result.
   * @returns {Promise<void>}
   */
  async revokeRefreshToken() {
    const refreshToken = this.tokens && this.tokens.refresh_token;
    if (!refreshToken) {
      this.tokens = null;
      return;
    }
    try {
      const accountsDomain = this.getAccountsDomain();
      const params = new URLSearchParams({ token: refreshToken });
      await this.http.post(`${accountsDomain}/oauth/v2/token/revoke`, params.toString(), {
        headers: { 'Content-Type': 'application/x-www-form-urlencoded' }
      });
      this.log.logInfo('Refresh token revoked.', 'AuthService.revokeRefreshToken');
    } catch (error) {
      this.log.logError(error.response?.data || error, 'AuthService.revokeRefreshToken');
    } finally {
      this.tokens = null;
    }
  }

  /**
   * Retrieve API Base URL (stored api_domain or fallback from DC).
   * @returns {string} The base API url for CRM queries.
   */
  getApiBaseUrl() {
    if (this.tokens && this.tokens.api_domain) {
      return this.tokens.api_domain;
    }
    const dc = this.getDc();
    return `https://www.zohoapis.${dc}`;
  }

  /**
   * Content upload domain (bulk-write file uploads live on content.zohoapis,
   * not the regular API domain). Derived from the stored api_domain when
   * possible so sandbox/China DCs keep their suffix.
   * @returns {string} The content API base url.
   */
  getContentBaseUrl() {
    const apiBase = this.getApiBaseUrl();
    const m = apiBase.match(/^https:\/\/[^.]+\.(zohoapis\.[a-z.]+)$/i);
    if (m) return `https://content.${m[1]}`;
    return `https://content.zohoapis.${this.getDc()}`;
  }
}

// Default export stays the shared singleton (unchanged behaviour for the CLI and
// web server, both of which import this module and rely on the instance). The
// class is attached so hosts that need per-connection instances — or tests that
// want throwaway instances — can construct their own via `.AuthService`.
const authService = new AuthService();
authService.AuthService = AuthService;
module.exports = authService;
