const fs = require('fs-extra');
const path = require('path');
const os = require('os');

const CONFIG_DIR = path.join(os.homedir(), '.zcrm');
const CONFIG_FILE = path.join(CONFIG_DIR, 'config.json');

/**
 * Handles persistence of CLI credentials and session tokens globally.
 */
class ConfigStore {
  constructor() {
    /** @type {object|null} */
    this.config = null;
    this.load();
  }

  /**
   * Loads the configuration from the JSON storage file.
   * Falls back to an empty object if the file doesn't exist or is corrupted.
   * @returns {void}
   */
  load() {
    try {
      if (fs.existsSync(CONFIG_FILE)) {
        this.config = fs.readJsonSync(CONFIG_FILE);
      } else {
        this.config = {};
      }
    } catch (error) {
      this.config = {};
    }
  }

  /**
   * Merges and saves the provided data to the configuration file.
   * @param {object} data - The configuration key-value pairs to store.
   * @returns {void}
   */
  save(data) {
    try {
      this.config = { ...this.config, ...data };
      fs.ensureDirSync(CONFIG_DIR);
      // Tokens are stored here in plaintext, so restrict access to the owner.
      try { fs.chmodSync(CONFIG_DIR, 0o700); } catch (permErr) { /* best-effort (no-op on Windows) */ }
      fs.writeJsonSync(CONFIG_FILE, this.config, { spaces: 2, mode: 0o600 });
      try { fs.chmodSync(CONFIG_FILE, 0o600); } catch (permErr) { /* best-effort (no-op on Windows) */ }
    } catch (error) {
      console.error('Failed to write configuration:', error.message);
    }
  }

  /**
   * Re-reads the configuration from disk, refreshing the in-memory cache.
   * Use this when another process may have written newer credentials/tokens.
   * @returns {object} The refreshed configuration object.
   */
  reload() {
    this.load();
    return this.config;
  }

  /**
   * Retrieves a single configuration value by key (from the in-memory cache,
   * which is kept current by load()/save()/reload()).
   * @param {string} key - The configuration property name.
   * @returns {*} The configuration value.
   */
  get(key) {
    return this.config ? this.config[key] : undefined;
  }

  /**
   * Retrieves all configuration values from the in-memory cache.
   * @returns {object} The entire configuration object.
   */
  getAll() {
    return this.config;
  }

  /**
   * Deletes the configuration file and resets the memory state.
   * @returns {void}
   */
  clear() {
    try {
      if (fs.existsSync(CONFIG_FILE)) {
        fs.unlinkSync(CONFIG_FILE);
      }
      this.config = {};
    } catch (error) {
      console.error('Failed to clear configuration:', error.message);
    }
  }
}

module.exports = new ConfigStore();
