const axios = require('axios');
const authService = require('../services/authService');
const { logError, logInfo } = require('./logger');

// Create base instance
const apiClient = axios.create({
  timeout: 30000 // 30 seconds timeout
});

// Helper to delay execution (for rate limit retries)
const delay = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

// ---------------------------------------------------------------------------
// Global concurrency gate
// ---------------------------------------------------------------------------
// Zoho CRM enforces a per-org/app concurrency limit (5–25 simultaneous calls
// depending on edition). This semaphore caps the number of in-flight requests
// across the whole process, so the extractor can parallelize freely while we
// still stay within a safe number of concurrent calls. Retries/backoff for a
// request happen while it holds its slot, which naturally relieves pressure.
let maxConcurrency = Math.max(1, parseInt(process.env.ZCRM_CONCURRENCY, 10) || 5);
let activeRequests = 0;
const waiters = [];

function acquireSlot() {
  if (activeRequests < maxConcurrency) {
    activeRequests++;
    return Promise.resolve();
  }
  return new Promise((resolve) => waiters.push(resolve));
}

function releaseSlot() {
  if (waiters.length > 0) {
    // Hand the freed slot directly to the next waiter (active count unchanged).
    const next = waiters.shift();
    next();
  } else {
    activeRequests = Math.max(0, activeRequests - 1);
  }
}

/**
 * Sets the maximum number of concurrent API requests.
 * @param {number} n - Desired concurrency (clamped to >= 1).
 */
function setConcurrency(n) {
  const value = parseInt(n, 10);
  if (Number.isFinite(value) && value > 0) {
    maxConcurrency = value;
    // If the limit was raised, admit queued waiters up to the new ceiling.
    while (activeRequests < maxConcurrency && waiters.length > 0) {
      activeRequests++;
      waiters.shift()();
    }
  }
}

/**
 * Performs the actual GET request with automatic token refresh, rate-limit
 * retries, and error logging. Retries recurse within a single acquired
 * concurrency slot (see `get`).
 *
 * @param {string} endpoint - API endpoint starting with '/' (e.g. '/crm/v8/settings/modules')
 * @param {object} params - Optional query parameters
 * @param {number} retryCount - Tracking retries internally
 */
async function request(method, endpoint, params = {}, data = null, retryCount = 0, retry = true) {
  try {
    const accessToken = await authService.getAccessToken();
    const baseUrl = authService.getApiBaseUrl();
    const url = `${baseUrl}${endpoint}`;

    logInfo(`${method.toUpperCase()} request to ${url} (Retry: ${retryCount})`, 'apiClient.request');

    const headers = { 'Authorization': `Zoho-oauthtoken ${accessToken}` };
    // Zoho requires an explicit JSON content type on write requests — even when
    // the body is empty — otherwise it responds 415 MEDIA_TYPE_NOT_SUPPORTED.
    if (method && method.toLowerCase() !== 'get') {
      headers['Content-Type'] = 'application/json';
    }

    const response = await apiClient({ method, url, params, data, headers });

    // Zoho API sometimes returns error statuses inside a 200 OK response, e.g. code: 'INVALID_TOKEN'
    if (response.data && response.data.status === 'error') {
      throw new Error(`Zoho API Error: ${response.data.message || JSON.stringify(response.data)}`);
    }

    // 204 No Content (zero COQL rows, empty lists, some deletes) gives
    // response.data === ''. Normalize to {} so callers always receive an
    // object; an empty object stays safe for every `res.foo || []` consumer.
    if (response.status === 204 || response.data === '' || response.data === undefined) {
      return {};
    }

    return response.data;
  } catch (error) {
    const status = error.response?.status;
    const errorData = error.response?.data;

    logInfo(`Request to ${endpoint} failed. Status: ${status}, Message: ${JSON.stringify(errorData || error.message)}`, 'apiClient.get');

    // A 401 caused by a missing OAuth scope cannot be fixed by refreshing the
    // token (the new token has the same scopes), so fail fast instead of
    // refreshing and retrying twice (which just produced duplicate errors).
    const isScopeError = errorData?.code === 'OAUTH_SCOPE_MISMATCH' || /scope/i.test(errorData?.message || '');

    // Handle 401 Unauthorized (Expired token or session)
    if (status === 401 && !isScopeError && retryCount < 2 && retry) {
      logInfo('Received 401 Unauthorized. Forcing token refresh and retrying...', 'apiClient.request');
      try {
        await authService.refreshAccessToken();
        return await request(method, endpoint, params, data, retryCount + 1, retry);
      } catch (refreshErr) {
        logError(refreshErr, 'apiClient.get - Token refresh retry failed');
        throw error;
      }
    }

    // Handle 429 Too Many Requests (Rate limit / concurrency limit hit)
    if ((status === 429 || errorData?.code === 'TOO_MANY_REQUESTS') && retryCount < 5 && retry) {
      const waitTime = Math.pow(2, retryCount) * 1000; // 1s, 2s, 4s, 8s, 16s backoff
      logInfo(`Rate/concurrency limit hit (429). Retrying in ${waitTime}ms...`, 'apiClient.request');
      await delay(waitTime);
      return await request(method, endpoint, params, data, retryCount + 1, retry);
    }

    // Handle temporary network or server failures (5xx)
    if (status >= 500 && status < 600 && retryCount < 2 && retry) {
      const waitTime = 1000;
      logInfo(`Server error ${status}. Retrying in ${waitTime}ms...`, 'apiClient.request');
      await delay(waitTime);
      return await request(method, endpoint, params, data, retryCount + 1, retry);
    }

    throw error;
  }
}

/**
 * Perform a GET request to Zoho CRM API. Acquires a global concurrency slot
 * first so the total number of simultaneous in-flight calls stays within the
 * configured limit (see setConcurrency); the slot is held across any internal
 * retries and released when the request finally settles.
 *
 * @param {string} endpoint - API endpoint starting with '/'
 * @param {object} params - Optional query parameters
 * @returns {Promise<object>} The response payload.
 */
async function get(endpoint, params = {}) {
  await acquireSlot();
  try {
    return await request('get', endpoint, params, null, 0);
  } finally {
    releaseSlot();
  }
}

async function post(endpoint, data = {}, params = {}) {
  await acquireSlot();
  try {
    return await request('post', endpoint, params, data, 0);
  } finally {
    releaseSlot();
  }
}

/**
 * POST with NO automatic retry — for executing/mutating endpoints where a retry
 * could double-execute (e.g. running a Deluge function or creating a record). A
 * 401/429/5xx surfaces to the caller instead of being silently re-sent. Still
 * holds a concurrency slot for the single attempt.
 */
async function postNoRetry(endpoint, data = {}, params = {}) {
  await acquireSlot();
  try {
    return await request('post', endpoint, params, data, 0, false);
  } finally {
    releaseSlot();
  }
}

/**
 * Performs a multipart/form-data PUT — required by Zoho's V8 function code-push
 * endpoint, which only accepts the script as an uploaded file whose name ends
 * in `.ds`. Uses Node's built-in FormData/Blob (no extra dependency). Unlike
 * `get`/`post` this does not retry (a code push is a one-shot write), but it
 * shares the axios instance and the same OAuth header.
 *
 * @param {string} endpoint - API endpoint starting with '/'
 * @param {{fieldName?: string, content: string, filename: string, contentType?: string}} opts
 * @returns {Promise<object>} The response payload.
 */
async function putForm(endpoint, { fieldName = 'code', content, filename, contentType = 'text/plain' }) {
  const accessToken = await authService.getAccessToken();
  const baseUrl = authService.getApiBaseUrl();
  const url = `${baseUrl}${endpoint}`;
  logInfo(`PUT (multipart) request to ${url}`, 'apiClient.putForm');

  const form = new FormData();
  form.append(fieldName, new Blob([Buffer.from(content, 'utf-8')], { type: contentType }), filename);

  // axios sets the multipart Content-Type (with boundary) from the FormData body.
  const response = await apiClient({ method: 'put', url, data: form, headers: { 'Authorization': `Zoho-oauthtoken ${accessToken}` } });

  if (response.data && response.data.status === 'error') {
    throw new Error(`Zoho API Error: ${response.data.message || JSON.stringify(response.data)}`);
  }
  return response.data;
}

async function put(endpoint, data = {}, params = {}) {
  await acquireSlot();
  try {
    return await request('put', endpoint, params, data, 0);
  } finally {
    releaseSlot();
  }
}

async function patch(endpoint, data = {}, params = {}) {
  await acquireSlot();
  try {
    return await request('patch', endpoint, params, data, 0);
  } finally {
    releaseSlot();
  }
}

/**
 * DELETE request. Optional third argument sends a JSON request body — some
 * Zoho endpoints (e.g. notification disable variants) accept structured DELETE
 * payloads that cannot be expressed as query parameters.
 */
async function del(endpoint, params = {}, data = null) {
  await acquireSlot();
  try {
    return await request('delete', endpoint, params, data, 0);
  } finally {
    releaseSlot();
  }
}

/**
 * Universal dispatcher for the `zcrm api` proxy command. GET requests keep the
 * full retry/refresh behavior; mutating methods run single-shot (a retry could
 * double-execute the operation server-side).
 *
 * @param {string} method - HTTP verb (GET/POST/PUT/PATCH/DELETE, any case)
 * @param {string} endpoint - API endpoint starting with '/'
 * @param {object} [params] - Query parameters
 * @param {object|null} [data] - JSON body (ignored for GET)
 * @returns {Promise<object>} The response payload ({} on 204).
 */
async function rawRequest(method, endpoint, params = {}, data = null) {
  const verb = String(method || 'get').toLowerCase();
  const retry = verb === 'get';
  await acquireSlot();
  try {
    return await request(verb, endpoint, params, verb === 'get' ? null : data, 0, retry);
  } finally {
    releaseSlot();
  }
}

/**
 * Full-response variant: returns { status, headers, data } instead of the bare
 * payload, and supports an absolute URL + binary response — needed for async
 * job downloads (bulk read results) and the content.zohoapis upload domain.
 * Single-shot (no retry); caller decides how to handle failures.
 *
 * @param {string} method
 * @param {string} urlOrEndpoint - Absolute URL (https://...) or /crm/... endpoint
 * @param {{params?: object, data?: any, headers?: object, responseType?: string}} [opts]
 */
async function requestFull(method, urlOrEndpoint, opts = {}) {
  const accessToken = await authService.getAccessToken();
  const url = /^https?:\/\//i.test(urlOrEndpoint)
    ? urlOrEndpoint
    : `${authService.getApiBaseUrl()}${urlOrEndpoint}`;
  logInfo(`${String(method).toUpperCase()} (full) request to ${url}`, 'apiClient.requestFull');
  const headers = { 'Authorization': `Zoho-oauthtoken ${accessToken}`, ...(opts.headers || {}) };
  await acquireSlot();
  try {
    const response = await apiClient({
      method,
      url,
      params: opts.params || {},
      data: opts.data,
      headers,
      responseType: opts.responseType || 'json',
      // Redirects to pre-signed download hosts must not leak the OAuth header;
      // axios follows them with the same headers, so cap at none when binary.
      maxRedirects: opts.responseType === 'arraybuffer' ? 0 : 5,
      validateStatus: (s) => (s >= 200 && s < 300) || s === 302
    });
    return { status: response.status, headers: response.headers, data: response.data };
  } finally {
    releaseSlot();
  }
}

/**
 * Multipart/form-data POST — required by the bulk-write upload endpoint on the
 * content.zohoapis domain. Accepts either a UTF-8 string or a Buffer as the
 * file content, plus extra headers (feature/X-CRM-ORG). Single-shot.
 *
 * @param {string} urlOrEndpoint - Absolute URL or /crm/... endpoint
 * @param {{fieldName?: string, content: string|Buffer, filename: string, contentType?: string, headers?: object}} opts
 */
async function postForm(urlOrEndpoint, { fieldName = 'file', content, filename, contentType = 'application/octet-stream', headers = {} }) {
  const accessToken = await authService.getAccessToken();
  const url = /^https?:\/\//i.test(urlOrEndpoint)
    ? urlOrEndpoint
    : `${authService.getApiBaseUrl()}${urlOrEndpoint}`;
  logInfo(`POST (multipart) request to ${url}`, 'apiClient.postForm');

  const buf = Buffer.isBuffer(content) ? content : Buffer.from(content, 'utf-8');
  const form = new FormData();
  form.append(fieldName, new Blob([buf], { type: contentType }), filename);

  const response = await apiClient({
    method: 'post',
    url,
    data: form,
    headers: { 'Authorization': `Zoho-oauthtoken ${accessToken}`, ...headers }
  });
  if (response.data && response.data.status === 'error') {
    throw new Error(`Zoho API Error: ${response.data.message || JSON.stringify(response.data)}`);
  }
  return response.data;
}

module.exports = {
  get,
  post,
  postNoRetry,
  putForm,
  postForm,
  put,
  patch,
  del,
  rawRequest,
  requestFull,
  setConcurrency
};
