/**
 * Single-function operations for the `zcrm fn` command family:
 *   - runTest / executeTest : execute a Standalone Deluge function on the live
 *                             CRM (the function-editor "test" action). This
 *                             EXECUTES code and is intentionally OUTSIDE the
 *                             tool's read-only guarantee.
 *   - pullOne               : read-only fetch of one function's code into its
 *                             `.ds` file (same path/format the full `pull` uses).
 *
 * Verified contract (see docs/superpowers/specs/2026-06-09-fn-command-family-design.md):
 *   POST {api_domain}/crm/v7/settings/functions/{api_name}/actions/test
 *   body: {"functions":[{"script":"<full deluge>","arguments":{<map>}}]}
 *   -> {"functions":[{output, logs, network_logs, metrics, status}]}
 * Only Standalone-category functions resolve at that path.
 */
const fs = require('fs-extra');
const path = require('path');
const apiClient = require('../utils/apiClient');
const { formatDeluge } = require('../utils/delugeFormatter');
const { parseSignature } = require('../utils/delugeSignature');
const crmMetadataService = require('./metadata/crmMetadataService');
const { logInfo, logError } = require('../utils/logger');

const getNamespaceForCategory = crmMetadataService.getNamespaceForCategory;

/**
 * Lightweight error with a `code` so the CLI can map it to a clean message.
 * @param {string} message
 * @param {string} code
 */
function fnError(message, code) {
  const e = new Error(message);
  e.code = code;
  return e;
}

/** Fetch the org's function list (read-only). */
async function listFunctions() {
  const res = await apiClient.get('/crm/v8/settings/functions');
  return (res && res.functions) || [];
}

/**
 * Find a function entry by api_name, case-insensitively. Zoho lowercases the
 * generated code signature but preserves the api_name's case in metadata, so a
 * name parsed from a `.ds` (lowercase) must still match a cased api_name.
 */
async function findByApiName(apiName) {
  const target = String(apiName || '').toLowerCase();
  return (await listFunctions()).find((f) => String(f.api_name || '').toLowerCase() === target) || null;
}

/** True if the resolved target is a Standalone function. */
function isStandalone(resolved) {
  if (resolved.category) return /^standalone$/i.test(resolved.category);
  return resolved.namespace === 'standalone';
}

function assertStandalone(resolved) {
  // All function categories (standalone, automation, button, schedule, related_list, signals)
  // are supported by Zoho's test execution endpoint.
  return true;
}

/**
 * Resolve a `fn test` target into the script to run + its identity.
 * Local mode: input is a `.ds` path or an existing file — its contents are the
 * script. Live mode: input is an api_name — fetch the saved code from CRM.
 * @param {string} target
 * @returns {Promise<{mode:string, script:string, apiName:string, namespace:string, category:string|null, args:Array}>}
 */
async function resolveTarget(target) {
  const explicitDs = /\.ds$/i.test(target);
  const isFile = explicitDs || (await fs.pathExists(path.resolve(target)));

  if (isFile) {
    const filePath = path.resolve(target);
    if (!(await fs.pathExists(filePath))) {
      throw fnError(`Local .ds file not found: ${filePath}`, 'DS_NOT_FOUND');
    }
    const script = await fs.readFile(filePath, 'utf8');
    const sig = parseSignature(script);

    let apiName = sig.apiName;
    let namespace = sig.namespace;
    // Fall back to the "<namespace>.<apiName>.ds" filename convention.
    if (!apiName) {
      const base = path.basename(filePath, '.ds');
      const parts = base.split('.');
      if (parts.length >= 2) {
        namespace = namespace || parts[0];
        apiName = parts.slice(1).join('.');
      } else {
        apiName = base;
      }
    }
    if (!apiName) throw fnError(`Could not determine the function name from ${filePath}.`, 'NO_API_NAME');

    // Resolve the real function identity from CRM (case-insensitive) so the test
    // URL uses the actual api_name and the guard sees the real category. The
    // submitted script stays local. Best-effort: if not found (not created yet)
    // fall back to the lowercased parsed name and let the endpoint report it.
    let category = null;
    try {
      const fn = await findByApiName(apiName);
      if (fn) {
        apiName = fn.api_name;
        namespace = fn.nameSpace || getNamespaceForCategory(fn.category) || namespace;
        category = fn.category;
      } else {
        apiName = apiName.toLowerCase();
      }
    } catch (e) {
      apiName = apiName.toLowerCase();
    }

    return {
      mode: 'local',
      script,
      apiName,
      namespace: (namespace || '').toLowerCase().trim(),
      category,
      args: sig.args,
    };
  }

  // Live mode — fetch saved code by api_name.
  const fn = await findByApiName(target);
  if (!fn) throw fnError(`No function named "${target}" found in this org.`, 'FN_NOT_FOUND');
  const code = await apiClient.get(`/crm/v8/settings/functions/${fn.id}/code`);
  const namespace = (fn.nameSpace || getNamespaceForCategory(fn.category) || '').toLowerCase().trim();
  return {
    mode: 'live',
    script: typeof code === 'string' ? code : '',
    apiName: fn.api_name,
    namespace,
    category: fn.category || null,
    args: (fn.arguments || []).map((a) => ({ type: a.type, name: a.name })),
  };
}

/**
 * Persist a test run to <output>/crm/function_tests/<apiName>-<ts>.json.
 * Always saved (even on Deluge failure) for an auditable history.
 */
async function saveArtifact(outputDir, resolved, args, response) {
  const dir = path.join(path.resolve(outputDir || './metadata'), 'crm', 'function_tests');
  await fs.ensureDir(dir);
  const ts = new Date().toISOString().replace(/[:.]/g, '-');
  const filePath = path.join(dir, `${resolved.apiName}-${ts}.json`);
  await fs.writeJson(filePath, {
    ranAt: new Date().toISOString(),
    mode: resolved.mode,
    apiName: resolved.apiName,
    namespace: resolved.namespace,
    submittedScript: resolved.script,
    arguments: args || {},
    response,
  }, { spaces: 2 });
  return filePath;
}

/**
 * Execute an already-resolved target. Enforces the Standalone guard, POSTs the
 * test request, saves the artifact, and returns a structured result.
 * @param {{resolved:object, args?:object, outputDir?:string}} params
 */
async function executeTest({ resolved, args = {}, outputDir = './metadata' }) {
  assertStandalone(resolved);

  let runnerApiName = resolved.apiName;
  const isCategoryStandalone = resolved.category ? /^standalone$/i.test(resolved.category) : resolved.namespace === 'standalone';

  if (!isCategoryStandalone) {
    try {
      const allFns = await listFunctions();
      const standaloneFn = allFns.find((f) => /^standalone$/i.test(f.category || '') || (f.nameSpace || '').toLowerCase() === 'standalone');
      if (standaloneFn) {
        runnerApiName = standaloneFn.api_name;
        logInfo(`Target "${resolved.apiName}" (category: "${resolved.category || resolved.namespace}") testing via standalone runner "${runnerApiName}".`, 'functionService.executeTest');
      }
    } catch (e) {
      // Best effort fallback to resolved.apiName
    }
  }

  const body = { functions: [{ script: resolved.script, arguments: args || {} }] };
  const endpoint = `/crm/v7/settings/functions/${encodeURIComponent(runnerApiName)}/actions/test`;
  logInfo(`Executing test for function "${resolved.apiName}" (${resolved.mode} mode) via endpoint "${endpoint}".`, 'functionService.executeTest');

  let response;
  try {
    // Executing endpoint → NO auto-retry (a 429 retry could double-execute the
    // function). Falls back to post() when postNoRetry is unavailable.
    response = await (apiClient.postNoRetry || apiClient.post)(endpoint, body);
  } catch (err) {
    const data = err.response && err.response.data;
    if (data && data.code === 'INVALID_DATA') {
      throw fnError(
        `No function named "${runnerApiName}" exists in this org to execute the test. ` +
        `Ensure your function exists on Zoho CRM.`,
        'NAME_INVALID'
      );
    }
    logError(err, 'functionService.executeTest');
    throw err;
  }

  const fnResult = (response && response.functions && response.functions[0]) || {};
  const savedPath = await saveArtifact(outputDir, resolved, args, response);
  return {
    resolved,
    args: args || {},
    response,
    fnResult,
    savedPath,
    success: fnResult.status === 'success',
  };
}

/**
 * Resolve + execute in one call (no prompting). Used by tests and as a
 * convenience; the CLI uses resolveTarget + executeTest so it can prompt for
 * arguments between the two steps.
 */
async function runTest({ target, args = {}, outputDir = './metadata' }) {
  const resolved = await resolveTarget(target);
  return executeTest({ resolved, args, outputDir });
}

/**
 * Build the V8 create descriptor for a Standalone Deluge function. Casing and
 * mandatory fields are strict (verified): category must be 'Standalone',
 * language 'Deluge', plus runtime + source.
 * @param {{apiName:string, returnType?:string}} params
 */
function buildDescriptor({ apiName, returnType = 'void' }) {
  return {
    api_name: apiName,
    name: apiName,
    category: 'Standalone',
    language: 'Deluge',
    runtime: 'Deluge 1.0',
    source: 'crm',
    return_type: returnType || 'void',
  };
}

/**
 * Create an (empty) Standalone function stub on CRM. The descriptor MUST be sent
 * as a stringified-JSON `metadata` query param wrapped in a `functions` array —
 * the POST body is ignored for metadata.
 * @returns {Promise<string>} the new function id.
 */
/** Best-effort extraction of Zoho's error message from a thrown axios error. */
function zohoMessage(err) {
  const d = err && err.response && err.response.data;
  if (!d) return null;
  return (d.functions && d.functions[0] && d.functions[0].message) || d.message || null;
}

async function createStub({ apiName, returnType }) {
  const descriptor = buildDescriptor({ apiName, returnType });
  logInfo(`Creating standalone function stub "${apiName}" (return_type ${descriptor.return_type}).`, 'functionService.createStub');
  let res;
  try {
    // Mutating endpoint (creates a function) → NO auto-retry.
    res = await (apiClient.postNoRetry || apiClient.post)('/crm/v8/settings/functions', null, {
      metadata: JSON.stringify({ functions: [descriptor] }),
    });
  } catch (err) {
    // HTTP 4xx/5xx (e.g. duplicate name) → clean CliError, not the support footer.
    throw fnError(`Could not create function "${apiName}": ${zohoMessage(err) || err.message}`, 'CREATE_FAILED');
  }
  const r = (res && res.functions && res.functions[0]) || {};
  if (r.status !== 'success' || !r.details || !r.details.id) {
    throw fnError(`Could not create function "${apiName}": ${r.message || JSON.stringify(r)}`, 'CREATE_FAILED');
  }
  return r.details.id;
}

/**
 * Push Deluge code to an existing function by id, via a multipart PUT whose
 * uploaded file is named `script.ds` (the `.ds` extension is mandatory).
 */
async function pushCodeById(id, script) {
  logInfo(`Pushing code to function id ${id} (multipart, script.ds).`, 'functionService.pushCodeById');
  let res;
  try {
    res = await apiClient.putForm(`/crm/v8/settings/functions/${id}`, {
      fieldName: 'code', content: script, filename: 'script.ds', contentType: 'text/plain',
    });
  } catch (err) {
    // HTTP 4xx/5xx (e.g. a compile/validation rejection) → clean CliError.
    throw fnError(`Could not push code: ${zohoMessage(err) || err.message}`, 'PUSH_FAILED');
  }
  const r = (res && res.functions && res.functions[0]) || {};
  if (r.status && r.status !== 'success') {
    throw fnError(`Could not push code: ${r.message || JSON.stringify(r)}`, 'PUSH_FAILED');
  }
  return res;
}

/**
 * Create a Standalone function on CRM and materialize its `.ds` locally. With
 * `fromFile`, the file's code is pushed immediately after the stub is created.
 * @param {{apiName:string, returnType?:string, fromFile?:string, outputDir?:string}} params
 */
async function createFunction({ apiName, returnType, fromFile, outputDir = './metadata' }) {
  // Zoho lowercases the generated code signature, so we create the function
  // lowercase too — keeping api_name, code, and the .ds filename consistent.
  apiName = String(apiName || '').trim().toLowerCase();
  let script = null;
  let rt = returnType;

  if (fromFile) {
    const fp = path.resolve(fromFile);
    if (!(await fs.pathExists(fp))) throw fnError(`--from file not found: ${fp}`, 'DS_NOT_FOUND');
    script = await fs.readFile(fp, 'utf8');
    const sig = parseSignature(script);
    if (sig.namespace && sig.namespace.toLowerCase() !== 'standalone') {
      throw fnError(`--from must be a Standalone function; its signature is "${sig.namespace}.${sig.apiName}".`, 'NOT_STANDALONE');
    }
    if (sig.apiName && sig.apiName.toLowerCase() !== apiName) {
      throw fnError(`The .ds signature name "${sig.apiName}" does not match the requested name "${apiName}". Rename one so they match.`, 'NAME_MISMATCH');
    }
    // With --from, the .ds signature's return type wins (--return-type is ignored).
    rt = sig.returnType || rt || 'void';
  }

  const id = await createStub({ apiName, returnType: rt });

  let pushed = false;
  if (script) {
    try {
      await pushCodeById(id, script);
      pushed = true;
    } catch (err) {
      // The stub now exists on CRM — guide the user to fix + push instead of re-creating.
      err.message = `${err.message} — but an empty function "${apiName}" was already created. Fix the .ds, then run: zcrm fn push <file>`;
      throw err;
    }
  }

  // Materialize the local .ds from the new id directly (avoids a name re-lookup
  // that could miss due to eventual consistency; tolerates empty code on a fresh
  // stub by falling back to what we know the code is).
  const fallbackScript = script || `${rt || 'void'} standalone.${apiName}()\n{\n}\n`;
  const filePath = await materializeDs({ id, apiName, namespace: 'standalone', outputDir, allowEmpty: true, fallbackScript });
  return { apiName, id, pushed, filePath };
}

/**
 * Push (save) a local `.ds` file's code to its matching live function. The
 * function must already exist (create it first with `createFunction`).
 * @param {{file:string, outputDir?:string}} params
 */
async function pushCode({ file, outputDir = './metadata' }) {
  const fp = path.resolve(file);
  if (!(await fs.pathExists(fp))) throw fnError(`.ds file not found: ${fp}`, 'DS_NOT_FOUND');
  const script = await fs.readFile(fp, 'utf8');
  const sig = parseSignature(script);

  let apiName = sig.apiName;
  if (!apiName) {
    const base = path.basename(fp, '.ds');
    const parts = base.split('.');
    apiName = parts.length >= 2 ? parts.slice(1).join('.') : base;
  }
  if (!apiName) throw fnError(`Could not determine the function name from ${fp}.`, 'NO_API_NAME');
  apiName = apiName.toLowerCase();

  const fn = await findByApiName(apiName);
  if (!fn) throw fnError(`No function named "${apiName}" exists in this org. Create it first: zcrm fn create ${apiName} --from "${file}"`, 'FN_NOT_FOUND');

  await pushCodeById(fn.id, script);
  return { apiName: fn.api_name, id: fn.id, category: fn.category || null, filePath: fp };
}

/**
 * Read-only: fetch a single function's Deluge code and write its `.ds` into the
 * metadata tree, using the same path/format as the full `pull`. Never deletes
 * anything (no stale sweep) — `pull` is left entirely intact.
 * @param {{apiName:string, outputDir?:string}} params
 */
/**
 * Fetch a function's code by id and write its formatted `.ds` into the metadata
 * tree (crm/functions/<namespace>/). Shared by `pullOne` and `createFunction`.
 * With `allowEmpty`, a blank/unavailable code response falls back to
 * `fallbackScript` (or a minimal stub) instead of throwing — used right after a
 * create, where the code may be empty or not yet propagated.
 * @returns {Promise<string>} the written file path.
 */
async function materializeDs({ id, apiName, namespace = 'standalone', outputDir = './metadata', allowEmpty = false, fallbackScript = null }) {
  let code;
  try {
    code = await apiClient.get(`/crm/v8/settings/functions/${id}/code`);
  } catch (err) {
    if (!allowEmpty) throw err;
    code = null;
  }

  let script;
  if (code && typeof code === 'string' && code.trim()) script = code;
  else if (allowEmpty) script = fallbackScript || `void standalone.${apiName}()\n{\n}\n`;
  else throw fnError(`Empty script code returned for "${apiName}".`, 'EMPTY_CODE');

  const ns = (namespace || 'standalone').toLowerCase().trim();
  const dir = path.join(path.resolve(outputDir || './metadata'), 'crm', 'functions', ns);
  await fs.ensureDir(dir);
  // Use the api_name verbatim — same filename the full `pull` produces, so the
  // two never diverge (which on case-sensitive filesystems would make a re-pull
  // sweep the fn-written file). Functions created via `fn create` are already
  // lowercase, so their files are lowercase regardless.
  const filePath = path.join(dir, `${ns}.${apiName}.ds`);
  await fs.outputFile(filePath, formatDeluge(script), 'utf8');
  return filePath;
}

async function pullOne({ apiName, outputDir = './metadata' }) {
  const fn = await findByApiName(apiName);
  if (!fn) throw fnError(`No function named "${apiName}" found in this org.`, 'FN_NOT_FOUND');

  const ns = (fn.nameSpace || getNamespaceForCategory(fn.category) || 'standalone').toLowerCase().trim();
  const filePath = await materializeDs({ id: fn.id, apiName: fn.api_name, namespace: ns, outputDir, allowEmpty: false });
  return { apiName: fn.api_name, category: fn.category || null, namespace: ns, filePath };
}

/**
 * Read-only: fetch a single function's current live Deluge code WITHOUT writing
 * anything to disk. Returns the formatted code (same `formatDeluge` funnel the
 * pull uses, so it compares hash-equal to the pulled `.ds`), or null when no
 * such function exists. Used by the extension's conflict guard to detect
 * divergence before a push.
 * @param {string} apiName
 * @returns {Promise<{apiName:string, id:string, code:string}|null>}
 */
async function getRemoteCode(apiName) {
  const fn = await findByApiName(apiName);
  if (!fn) return null;
  const code = await apiClient.get(`/crm/v8/settings/functions/${fn.id}/code`);
  const script = typeof code === 'string' ? code : '';
  return { apiName: fn.api_name, id: fn.id, code: formatDeluge(script) };
}

module.exports = {
  resolveTarget,
  executeTest,
  runTest,
  pullOne,
  getRemoteCode,
  createFunction,
  pushCode,
  isStandalone,
  assertStandalone,
  buildDescriptor,
  // exposed for tests
  _saveArtifact: saveArtifact,
  _findByApiName: findByApiName,
};
