const path = require('path');
const fs = require('fs-extra');
const BaseMetadataService = require('./baseMetadataService');
const apiClient = require('../../utils/apiClient');
const { mapWithConcurrency } = require('../../utils/concurrency');
const { sweepDir, sweepDeletedDirs, normalizePath } = require('../../utils/fsSync');
const { logError, logInfo, addSessionLog, removeSessionLog } = require('../../utils/logger');
const { formatDeluge } = require('../../utils/delugeFormatter');
const { buildResultReadme } = require('../../utils/readmeTemplate');
const pkg = require('../../../package.json');

const STORAGE_DIR = path.join(process.cwd(), 'storage/metadata');

// Default number of concurrent Zoho API calls. 5 is the Free-edition org
// concurrency limit, so it is safe for every edition; higher editions can opt
// into more via the --concurrency flag.
const DEFAULT_CONCURRENCY = 5;

// A `.zcrm/.store/.sync-in-progress` lock older than this is treated as a
// leftover from a crashed run and reclaimed. Full pulls on large orgs run for
// minutes, not hours, so 10 minutes comfortably covers a live run.
const LOCK_STALE_MS = 10 * 60 * 1000;

/**
 * Normalizes custom function category names to their lowercase/underscored namespaces.
 * @param {string} category
 * @returns {string} Normalized namespace
 */
function getNamespaceForCategory(category) {
  const cat = (category || '').toLowerCase().trim();
  switch (cat) {
    case 'standalone':
      return 'standalone';
    case 'automation':
      return 'automation';
    case 'button':
      return 'button';
    case 'related list':
    case 'related_list':
      return 'related_list';
    case 'schedule':
      return 'schedule';
    case 'signals':
      return 'salessignals';
    default:
      return cat.replace(/\s+/g, '_') || 'standalone';
  }
}

/**
 * Makes an arbitrary string safe to use as a file/directory name across
 * platforms (strips illegal characters, collapses whitespace, trims trailing
 * dots/spaces which Windows forbids, and caps the length).
 * @param {*} name
 * @returns {string}
 */
function sanitizeFileName(name) {
  const cleaned = String(name == null ? '' : name)
    .replace(/[\\/:*?"<>|]/g, '_')
    .replace(/\s+/g, '_')
    .replace(/_+/g, '_');
  const truncated = cleaned.slice(0, 120).replace(/^[._]+|[._]+$/g, '');
  return truncated || 'unnamed';
}

/**
 * Returns the first non-empty string value among the candidate fields (used to
 * locate a template's HTML body, whose field name varies by template type).
 * @param {object} item
 * @param {string[]} fields
 * @returns {string|null}
 */
function pickHtmlContent(item, fields) {
  if (!item) return null;
  for (const field of fields) {
    const value = item[field];
    if (typeof value === 'string' && value.trim().length > 0) return value;
  }
  return null;
}

/**
 * Metadata extractor service implementation for Zoho CRM V8.
 */
class CrmMetadataService extends BaseMetadataService {
  constructor() {
    super('Zoho CRM');
  }

  /**
   * Run the Zoho CRM metadata extraction process.
   *
   * Files are overwritten in place and tracked; at the end, local files that
   * were not refreshed this run (within scopes whose authoritative fetch
   * succeeded) are deleted — these represent records deleted on Zoho CRM. A
   * partial/failed run therefore never wipes existing data.
   *
   * @param {Function} onProgress - Callback (stage, message, details) for status.
   * @param {string} [outputDir] - Destination folder path. Defaults to local workspace storage.
   * @param {object} [options] - Extra options.
   * @param {number} [options.concurrency] - Max concurrent Zoho API calls (1-25).
   * @returns {Promise<object>} Extraction statistics.
   */
  async extract(onProgress, outputDir = STORAGE_DIR, options = {}) {
    const finalOutputDir = outputDir;
    const zcrmMetaDir = path.join(finalOutputDir, 'crm', 'meta');
    const zcrmStoreDir = path.join(finalOutputDir, '.zcrm', '.store');
    const zcrmOrgDir = path.join(finalOutputDir, '.zcrm', '.org');
    const modulesDir = path.join(zcrmMetaDir, 'modules');
    const functionsDir = path.join(finalOutputDir, 'crm', 'functions');

    // Cap simultaneous Zoho API calls to respect the org concurrency limit.
    const concurrency = Math.max(1, Math.min(25, parseInt(options.concurrency, 10) || DEFAULT_CONCURRENCY));
    apiClient.setConcurrency(concurrency);

    // Per-module record counts read RECORD DATA (not schema) and cost ~50 API
    // credits per module, so they are strictly opt-in. Default pulls stay
    // metadata-only with no record-data access.
    const withCounts = options.withCounts === true;

    // Path of the debug log written into the output folder (set once the run
    // starts; declared here so the finally block can stop mirroring to it).
    let outputLogPath = null;

    // Track every file written this run so stale files can be swept afterward.
    const writtenFiles = new Set();
    const recordWrite = (p) => writtenFiles.add(normalizePath(p));
    const outJson = async (p, data, opts) => { await fs.outputJson(p, data, opts); recordWrite(p); };
    const outFile = async (p, data, enc) => { await fs.outputFile(p, data, enc); recordWrite(p); };

    // Cross-process sync lock (.zcrm/.store/.sync-in-progress): the CLI and the
    // VS Code extension share this exact folder layout, so two concurrent pulls
    // into the same root would race the stale sweep. The lock file is NOT
    // registered in writtenFiles (it must survive the sweep bookkeeping) and is
    // always removed in the finally block below.
    const lockPath = path.join(zcrmStoreDir, '.sync-in-progress');
    try {
      const lockStat = await fs.stat(lockPath);
      if (Date.now() - lockStat.mtimeMs < LOCK_STALE_MS) {
        let holder = 'another process';
        try { holder = (await fs.readJson(lockPath)).tool || holder; } catch (readErr) { /* unreadable lock — keep generic holder */ }
        const busyErr = new Error(
          `Another metadata sync (${holder}) is already running for this folder. ` +
          `Wait for it to finish, or delete "${lockPath}" if that run crashed.`
        );
        busyErr.code = 'SYNC_IN_PROGRESS';
        throw busyErr;
      }
      logInfo(`Reclaiming stale sync lock (older than ${LOCK_STALE_MS / 60000} min): ${lockPath}`, 'CrmMetadataService.extract');
    } catch (lockErr) {
      if (lockErr.code === 'SYNC_IN_PROGRESS') throw lockErr;
      // ENOENT (no lock) or an unreadable stat: proceed and take the lock.
    }
    await fs.outputJson(lockPath, {
      pid: process.pid,
      tool: process.env.ZCRM_CLI_MODE === 'true' ? 'zcrm-cli' : 'zcrm-embedded',
      started_at: new Date().toISOString()
    });

    // Remove only obsolete layout artifacts from older CLI versions. The current
    // crm/ and .zcrm/ trees are refreshed in place and reconciled at the end,
    // so an interrupted run keeps the last-good data instead of wiping it.
    try {
      for (const legacy of ['modules', 'Functions', 'functions', 'export', 'extra', 'org.json', 'modules.json', 'index.json']) {
        await fs.remove(path.join(finalOutputDir, legacy));
      }
    } catch (rmErr) {
      logInfo(`Could not clean legacy metadata files: ${rmErr.message}`, 'CrmMetadataService.extract');
    }

    const stats = {
      startedAt: new Date().toISOString(),
      modulesProcessed: 0,
      totalFields: 0,
      totalLayouts: 0,
      totalRelatedLists: 0,
      totalCustomViews: 0,
      removedStale: 0,
      concurrency,
      skipped: 0,
      errors: []
    };

    // Keep an in-memory object to merge all response data
    const completeMetadata = {
      org: null,
      modules: [],
      modules_details: {},
      fields: {},
      layouts: {},
      related_lists: {},
      custom_views: {},
      profiles: [],
      roles: [],
      webhooks: null,
      functions: null
    };

    const fieldMap = {};

    // Collected for the dynamically-generated result README.
    const moduleSummaries = [];
    const globalSettingsExtracted = [];
    let functionsCount = 0;
    let profilesCount = 0;
    let rolesCount = 0;

    // Records a failed sub-resource fetch. Many sub-resources simply don't apply
    // to every module/org — Zoho returns 400 ("module not supported", "layout
    // deactivated", "feature not enabled", etc.). Those are EXPECTED: they are
    // counted as `skipped` and logged quietly (file only) so they neither spam
    // the console nor corrupt the progress bar. Only genuinely unexpected
    // failures are recorded as `errors` and logged loudly. Pass optional=true
    // for supplementary resources whose absence is always normal.
    const EXPECTED_ERROR_CODES = new Set([
      'NO_PERMISSION', 'NOT_SUPPORTED', 'INVALID_MODULE', 'INVALID_URL_PATTERN',
      'FEATURE_NOT_ENABLED', 'REQUIRED_PARAM_MISSING', 'MANDATORY_NOT_FOUND', 'OAUTH_SCOPE_MISMATCH'
    ]);
    const EXPECTED_ERROR_RE = /not supported|not enabled|seems to be invalid|invalid module|deactivated|parameter is missing|expected parameter|no permission|not allowed|not available/i;

    const handleResourceError = (reason, endpoint, apiName, label, optional = false) => {
      const status = reason?.response?.status;
      const errCode = reason?.response?.data?.code;
      const errMsg = reason?.response?.data?.message || reason?.message || '';
      const expected = optional || EXPECTED_ERROR_CODES.has(errCode) || EXPECTED_ERROR_RE.test(errMsg);

      if (expected) {
        stats.skipped++;
        logInfo(`${label} not available for ${apiName} (${errCode || status || 'n/a'}): ${errMsg}`, 'CrmMetadataService.extract');
      } else {
        stats.errors.push({ endpoint, error: errMsg || String(reason) });
        logError(reason, `CrmMetadataService.extract - ${label}: ${apiName}`);
      }
    };

    try {
      // Create .zcrm internal structures
      await fs.ensureDir(path.join(finalOutputDir, '.zcrm', '.logs'));
      await fs.ensureDir(zcrmOrgDir);
      await fs.ensureDir(zcrmStoreDir);

      // Create log and audit placeholders (under .zcrm/.logs, which is never swept)
      const today = new Date();
      const year = today.getFullYear();
      const month = String(today.getMonth() + 1).padStart(2, '0');
      const date = String(today.getDate()).padStart(2, '0');
      const logFileName = `ZCRM-CLI-${year}-${month}-${date}.log`;
      outputLogPath = path.join(finalOutputDir, '.zcrm', '.logs', logFileName);
      await fs.outputJson(path.join(finalOutputDir, '.zcrm', '.logs', '.audit.json'), {}, { spaces: 2 });
      await fs.outputFile(outputLogPath, `[${today.toISOString()}] zcrm pull started (concurrency ${concurrency}${withCounts ? ', record counts ON' : ''}).\n`, 'utf8');
      // Mirror every subsequent log entry (including the quiet info/skip lines
      // suppressed from the console) into a debug log in the result folder.
      addSessionLog(outputLogPath);
      stats.logFile = outputLogPath;

      // 1. Fetch Org Information to get Org ID/Name
      onProgress('FETCH_ORG', 'Fetching CRM Organization details...');
      let orgName = 'Unknown Org';
      try {
        const orgResponse = await apiClient.get('/crm/v8/org');
        if (orgResponse && orgResponse.org && orgResponse.org.length > 0) {
          const org = orgResponse.org[0];
          orgName = org.company_name || org.zorg_id || 'Unknown Org';
          completeMetadata.org = org;
          await outJson(path.join(zcrmOrgDir, 'org.json'), orgResponse, { spaces: 2 });
          onProgress('FETCH_ORG_SUCCESS', `Org identified: ${orgName}`);
        }
      } catch (err) {
        logError(err, 'CrmMetadataService.extract - Org Details');
        stats.errors.push({ endpoint: '/crm/v8/org', error: err.message });
        onProgress('FETCH_ORG_WARNING', 'Could not fetch Org details. Proceeding with placeholder.');
      }

      // 1b. Write ZCRM Config files
      const authService = require('../authService');
      const dc = authService.getDc();
      const zcrmProj = {
        meta_directory: [
          {
            path: 'crm',
            default: true
          }
        ],
        name: orgName.replace(/\s+/g, '_') || 'ZCRMProject',
        accounts_url: `https://accounts.zoho.${dc}`,
        domain_url: `https://www.zohoapis.${dc}`,
        api_version: '6'
      };
      await outJson(path.join(finalOutputDir, 'zcrm-project.json'), zcrmProj, { spaces: 2 });

      await outJson(path.join(finalOutputDir, 'meta.json'), { resource_type: 'all' }, { spaces: 2 });
      await outFile(path.join(finalOutputDir, '.zcrmignore'), '# ZCRM CLI ignore file\n.zcrm/\n', 'utf8');
      // README.md is generated from the real pulled data at the end of extraction.

      // 2. Fetch Modules
      onProgress('FETCH_MODULES', 'Fetching list of CRM modules...');
      const modulesResponse = await apiClient.get('/crm/v8/settings/modules');
      const modules = modulesResponse.modules || [];
      completeMetadata.modules = modules;

      // The modules list is authoritative — any local module dir not in this set
      // belongs to a module deleted on Zoho CRM and is removed after the loop.
      const validModuleNames = new Set(modules.map(m => m.api_name).filter(Boolean));

      // Save modules list in store
      await outJson(path.join(zcrmStoreDir, 'modules.json'), modulesResponse, { spaces: 2 });
      onProgress('FETCH_MODULES_SUCCESS', `Found ${modules.length} modules.`);

      // Prepare metadata subdirectory under crm/meta/modules
      await fs.ensureDir(modulesDir);

      // 3. Iterate through every module and fetch its metadata (bounded concurrency)
      onProgress('MODULES_START', `Extracting metadata for ${modules.length} modules (concurrency: ${concurrency})...`, {
        total: modules.length,
        concurrency
      });

      let completedModules = 0;
      await mapWithConcurrency(modules, concurrency, async (module) => {
        const apiName = module.api_name;
        const singularLabel = module.singular_label || apiName;
        try {
          if (!apiName) return;

          // Skip modules that are explicitly not supported in the API
          if (module.api_supported === false) {
            logInfo(`Skipping module ${singularLabel} (${apiName}) because api_supported is false.`, 'CrmMetadataService.extract');
            stats.modulesProcessed++;
            return;
          }

          const moduleSubDir = path.join(modulesDir, apiName);
          await fs.ensureDir(moduleSubDir);

          // Sub-stats for summary.json
          const summary = {
            module_name: singularLabel,
            api_name: apiName,
            fields_count: 0,
            required_fields: [],
            lookup_fields: [],
            picklist_fields: [],
            formula_fields: [],
            multi_select_fields: [],
            subforms: [],
            layouts_count: 0,
            related_lists_count: 0
          };

          fieldMap[apiName] = {};

          // The module sub-resources are independent — fetch concurrently.
          // (Overall in-flight calls are still capped by the apiClient gate.)
          const subResourceCalls = [
            apiClient.get(`/crm/v8/settings/modules/${apiName}`),
            apiClient.get('/crm/v8/settings/fields', { module: apiName }),
            apiClient.get('/crm/v8/settings/layouts', { module: apiName }),
            apiClient.get('/crm/v8/settings/related_lists', { module: apiName }),
            apiClient.get('/crm/v8/settings/custom_views', { module: apiName }),
            apiClient.get('/crm/v8/settings/duplicate_check_preference', { module: apiName }),
            apiClient.get('/crm/v8/settings/record_locking_configurations', { module: apiName }),
            apiClient.get('/crm/v8/settings/tags', { module: apiName }),
            apiClient.get('/crm/v8/workflow_configurations', { module: apiName }),
            // Custom links are module-scoped; the endpoint requires the module param.
            apiClient.get('/crm/v8/settings/custom_links', { module: apiName })
          ];
          // Record count is opt-in (reads record data; ~50 credits/module).
          if (withCounts) {
            subResourceCalls.push(
              apiClient.get(`/crm/v8/${apiName}/actions/count`).catch(() => ({ count: 'unauthorized_or_unsupported' }))
            );
          }
          const [detailR, fieldsR, layoutsR, relatedR, viewsR, dupCheckR, lockConfigR, tagsR, workflowConfigR, customLinksR, countR] = await Promise.allSettled(subResourceCalls);

          // 3a. Module Details
          if (detailR.status === 'fulfilled') {
            completeMetadata.modules_details[apiName] = detailR.value || {};
            await outJson(path.join(moduleSubDir, `${apiName}.modules-meta.json`), detailR.value || {}, { spaces: 2 });
          } else {
            handleResourceError(detailR.reason, `/crm/v8/settings/modules/${apiName}`, apiName, 'Module Detail');
          }

          // 3b. Fields
          if (fieldsR.status === 'fulfilled') {
            const fieldsResponse = fieldsR.value;
            const hasFields = fieldsResponse && Array.isArray(fieldsResponse.fields);
            const fields = hasFields ? fieldsResponse.fields : [];
            completeMetadata.fields[apiName] = fields;

            if (hasFields && fields.length > 0) {
              const fieldsDir = path.join(moduleSubDir, 'fields');
              await fs.ensureDir(fieldsDir);
              for (const field of fields) {
                const fieldApiName = field.api_name;
                if (fieldApiName) {
                  await outJson(path.join(fieldsDir, `${fieldApiName}.fields-meta.json`), field, { spaces: 2 });
                }
              }
            }

            summary.fields_count = fields.length;
            stats.totalFields += fields.length;

            fields.forEach((field) => {
              const fieldApiName = field.api_name;
              const dataType = field.data_type || 'text';
              if (!fieldApiName) return;

              fieldMap[apiName][fieldApiName] = dataType;

              if (field.system_mandatory === true || field.required === true) summary.required_fields.push(fieldApiName);
              if (dataType === 'lookup' || field.lookup) summary.lookup_fields.push(fieldApiName);
              if (dataType === 'picklist') summary.picklist_fields.push(fieldApiName);
              if (dataType === 'formula' || field.formula) summary.formula_fields.push(fieldApiName);
              if (dataType === 'multiselectpicklist') summary.multi_select_fields.push(fieldApiName);
              if (dataType === 'subform') summary.subforms.push(fieldApiName);
            });
          } else {
            handleResourceError(fieldsR.reason, `/crm/v8/settings/fields?module=${apiName}`, apiName, 'Fields');
          }

          // 3c. Layouts
          if (layoutsR.status === 'fulfilled') {
            const layoutsResponse = layoutsR.value;
            const hasLayouts = layoutsResponse && Array.isArray(layoutsResponse.layouts);
            const layouts = hasLayouts ? layoutsResponse.layouts : [];
            completeMetadata.layouts[apiName] = layouts;

            if (hasLayouts && layouts.length > 0) {
              const layoutsDir = path.join(moduleSubDir, 'layouts');
              const mapDepDir = path.join(layoutsDir, 'map_dependencies');
              await fs.ensureDir(layoutsDir);
              for (const layout of layouts) {
                const layoutApiName = layout.api_name || layout.name;
                const layoutId = layout.id;
                if (layoutApiName) {
                  await outJson(path.join(layoutsDir, `${layoutApiName}.layouts-meta.json`), layout, { spaces: 2 });
                }
                if (layoutId) {
                  try {
                    const depR = await apiClient.get(`/crm/v8/settings/layouts/${layoutId}/map_dependency`, { module: apiName });
                    if (depR && Array.isArray(depR.map_dependency) && depR.map_dependency.length > 0) {
                      await fs.ensureDir(mapDepDir);
                      await outJson(path.join(mapDepDir, `${layoutId}.json`), depR, { spaces: 2 });
                    }
                  } catch (depErr) {
                    handleResourceError(depErr, `/crm/v8/settings/layouts/${layoutId}/map_dependency?module=${apiName}`, apiName, 'Layout Map Dependency', true);
                  }
                }
              }
            }

            summary.layouts_count = layouts.length;
            stats.totalLayouts += layouts.length;
          } else {
            handleResourceError(layoutsR.reason, `/crm/v8/settings/layouts?module=${apiName}`, apiName, 'Layouts');
          }

          // 3d. Related Lists
          if (relatedR.status === 'fulfilled') {
            const relatedResponse = relatedR.value;
            const hasRelated = relatedResponse && Array.isArray(relatedResponse.related_lists);
            const relatedLists = hasRelated ? relatedResponse.related_lists : [];
            completeMetadata.related_lists[apiName] = relatedLists;

            if (hasRelated && relatedLists.length > 0) {
              const relatedDir = path.join(moduleSubDir, 'related_lists');
              await fs.ensureDir(relatedDir);
              for (const list of relatedLists) {
                const listApiName = list.api_name;
                if (listApiName) {
                  await outJson(path.join(relatedDir, `${listApiName}.related_lists-meta.json`), list, { spaces: 2 });
                }
              }
            }

            summary.related_lists_count = relatedLists.length;
            stats.totalRelatedLists += relatedLists.length;
          } else {
            handleResourceError(relatedR.reason, `/crm/v8/settings/related_lists?module=${apiName}`, apiName, 'Related Lists');
          }

          // 3e. Custom Views
          let viewsCount = 0;
          if (viewsR.status === 'fulfilled') {
            const customViewsResponse = viewsR.value;
            const hasViews = customViewsResponse && Array.isArray(customViewsResponse.custom_views);
            const customViews = hasViews ? customViewsResponse.custom_views : [];
            completeMetadata.custom_views[apiName] = customViews;

            if (hasViews && customViews.length > 0) {
              const viewsDir = path.join(moduleSubDir, 'custom_views');
              await fs.ensureDir(viewsDir);
              for (const view of customViews) {
                const viewApiName = view.api_name || view.id;
                if (viewApiName) {
                  await outJson(path.join(viewsDir, `${viewApiName}.custom_views-meta.json`), view, { spaces: 2 });
                }
              }
            }

            viewsCount = customViews.length;
            stats.totalCustomViews += customViews.length;
          } else {
            handleResourceError(viewsR.reason, `/crm/v8/settings/custom_views?module=${apiName}`, apiName, 'Custom Views');
          }

          // 3e-1. Duplicate Check Preference
          if (dupCheckR.status === 'fulfilled') {
             const dupResp = dupCheckR.value;
             if (dupResp && dupResp.duplicate_check_preference) {
                 await outJson(path.join(moduleSubDir, 'duplicate_check_preference.json'), dupResp, { spaces: 2 });
             }
          } else {
            handleResourceError(dupCheckR.reason, `/crm/v8/settings/duplicate_check_preference?module=${apiName}`, apiName, 'Duplicate Check Preference', true);
          }

          // 3e-2. Record Locking Configurations
          let lockHasItems = false;
          if (lockConfigR.status === 'fulfilled') {
             const lockResp = lockConfigR.value;
             if (lockResp && Array.isArray(lockResp.record_locking_configurations) && lockResp.record_locking_configurations.length > 0) {
                 lockHasItems = true;
                 const lockDir = path.join(moduleSubDir, 'record_locking_configurations');
                 await fs.ensureDir(lockDir);
                 for (const config of lockResp.record_locking_configurations) {
                     const configId = config.id || config.name;
                     if (configId) {
                         await outJson(path.join(lockDir, `${configId}.json`), config, { spaces: 2 });
                     }
                 }
             }
          } else {
            handleResourceError(lockConfigR.reason, `/crm/v8/settings/record_locking_configurations?module=${apiName}`, apiName, 'Record Locking Configurations', true);
          }

          // 3e-3. Tags
          let tagsHasItems = false;
          if (tagsR.status === 'fulfilled') {
             const tagsResp = tagsR.value;
             if (tagsResp && Array.isArray(tagsResp.tags) && tagsResp.tags.length > 0) {
                 tagsHasItems = true;
                 const tagsDir = path.join(moduleSubDir, 'tags');
                 await fs.ensureDir(tagsDir);
                 for (const tag of tagsResp.tags) {
                     const tagId = tag.id || tag.name;
                     if (tagId) {
                         await outJson(path.join(tagsDir, `${tagId}.json`), tag, { spaces: 2 });
                     }
                 }
             }
          } else {
            handleResourceError(tagsR.reason, `/crm/v8/settings/tags?module=${apiName}`, apiName, 'Tags', true);
          }

          // 3e-4. Workflow Configurations
          let wfHasItems = false;
          if (workflowConfigR.status === 'fulfilled') {
             const wfResp = workflowConfigR.value;
             if (wfResp && Array.isArray(wfResp.workflow_configurations) && wfResp.workflow_configurations.length > 0) {
                 wfHasItems = true;
                 const wfDir = path.join(moduleSubDir, 'workflow_configurations');
                 await fs.ensureDir(wfDir);
                 for (const config of wfResp.workflow_configurations) {
                     const configId = config.id || config.name;
                     if (configId) {
                         await outJson(path.join(wfDir, `${configId}.json`), config, { spaces: 2 });
                     }
                 }
             }
          } else {
            handleResourceError(workflowConfigR.reason, `/crm/v8/workflow_configurations?module=${apiName}`, apiName, 'Workflow Configurations', true);
          }

          // 3e-4b. Custom Links (module-scoped)
          let customLinksHasItems = false;
          if (customLinksR.status === 'fulfilled') {
             const clResp = customLinksR.value;
             if (clResp && Array.isArray(clResp.custom_links) && clResp.custom_links.length > 0) {
                 customLinksHasItems = true;
                 const clDir = path.join(moduleSubDir, 'custom_links');
                 await fs.ensureDir(clDir);
                 for (const link of clResp.custom_links) {
                     const linkId = link.id || link.name;
                     if (linkId) {
                         await outJson(path.join(clDir, `${linkId}.json`), link, { spaces: 2 });
                     }
                 }
             }
          } else {
            handleResourceError(customLinksR.reason, `/crm/v8/settings/custom_links?module=${apiName}`, apiName, 'Custom Links', true);
          }

          // 3e-5. Record Count (actions/count) — only when --with-counts is set.
          if (withCounts) {
            if (countR && countR.status === 'fulfilled' && countR.value && countR.value.count !== undefined) {
               summary.records_count = countR.value.count;
            } else {
               summary.records_count = 'unknown';
            }
          }

          // 3f. Save summary.json
          await outJson(path.join(moduleSubDir, 'summary.json'), summary, { spaces: 2 });

          // 3g. Sweep deleted sub-resources. A resource is reconciled only when
          // its listing was fetched successfully AND returned at least one item
          // (count > 0 implies fulfilled + non-empty). This guarantees that a
          // transient failure OR an anomalous empty response never deletes a
          // module's existing good data — we only ever remove individual items
          // that are genuinely absent from a populated listing.
          // Accumulate in a per-worker local, then fold into shared stats with a
          // single synchronous add (workers run concurrently — `+= await` on a
          // shared field would lose updates).
          let sweptInModule = 0;
          if (summary.fields_count > 0) sweptInModule += await sweepDir(path.join(moduleSubDir, 'fields'), writtenFiles);
          if (summary.layouts_count > 0) {
            sweptInModule += await sweepDir(path.join(moduleSubDir, 'layouts'), writtenFiles);
            if (await fs.pathExists(path.join(moduleSubDir, 'layouts', 'map_dependencies'))) {
              sweptInModule += await sweepDir(path.join(moduleSubDir, 'layouts', 'map_dependencies'), writtenFiles);
            }
          }
          if (summary.related_lists_count > 0) sweptInModule += await sweepDir(path.join(moduleSubDir, 'related_lists'), writtenFiles);
          if (viewsCount > 0) sweptInModule += await sweepDir(path.join(moduleSubDir, 'custom_views'), writtenFiles);
          // Reconcile the new per-module resources only when this run fetched them
          // successfully and non-empty — a transient failure must not delete them.
          if (lockHasItems) sweptInModule += await sweepDir(path.join(moduleSubDir, 'record_locking_configurations'), writtenFiles);
          if (tagsHasItems) sweptInModule += await sweepDir(path.join(moduleSubDir, 'tags'), writtenFiles);
          if (wfHasItems) sweptInModule += await sweepDir(path.join(moduleSubDir, 'workflow_configurations'), writtenFiles);
          if (customLinksHasItems) sweptInModule += await sweepDir(path.join(moduleSubDir, 'custom_links'), writtenFiles);
          stats.removedStale += sweptInModule;

          moduleSummaries.push({
            api_name: apiName,
            label: singularLabel,
            custom: module.custom === true,
            fields: summary.fields_count,
            layouts: summary.layouts_count,
            related_lists: summary.related_lists_count
          });
          stats.modulesProcessed++;
        } catch (modErr) {
          stats.errors.push({ endpoint: `module:${apiName}`, error: modErr.message });
          logError(modErr, `CrmMetadataService.extract - Module: ${apiName}`);
        } finally {
          completedModules++;
          onProgress('MODULE_PROGRESS', `[${completedModules}/${modules.length}] Extracted: ${singularLabel}`, {
            completed: completedModules,
            total: modules.length,
            module: apiName
          });
        }
      });

      // 3h. Remove module folders for modules deleted on Zoho CRM. Only when the
      // modules list came back non-empty — an empty list would otherwise wipe
      // every module folder.
      if (validModuleNames.size > 0) {
        const removedModuleDirs = await sweepDeletedDirs(modulesDir, validModuleNames);
        stats.removedStale += removedModuleDirs;
      }

      // 4. Retrieve Webhooks
      onProgress('FETCH_WEBHOOKS', 'Fetching CRM automation webhooks...');
      try {
        const webhooksResponse = await apiClient.get('/crm/v8/settings/automation/webhooks');
        completeMetadata.webhooks = webhooksResponse;
        await outJson(path.join(zcrmStoreDir, 'webhooks.json'), webhooksResponse, { spaces: 2 });
        onProgress('FETCH_WEBHOOKS_SUCCESS', 'Webhooks retrieved successfully.');
      } catch (err) {
        logError(err, 'CrmMetadataService.extract - Webhooks');
        stats.errors.push({ endpoint: '/crm/v8/settings/automation/webhooks', error: err.message });
        onProgress('FETCH_WEBHOOKS_WARNING', 'Could not fetch webhooks (check api permissions).');
      }

      // 4b. Fetch Profiles
      onProgress('FETCH_PROFILES', 'Fetching CRM settings profiles...');
      try {
        const profilesResponse = await apiClient.get('/crm/v8/settings/profiles');
        const profiles = profilesResponse.profiles || [];
        completeMetadata.profiles = profiles;
        profilesCount = profiles.length;
        const profilesDir = path.join(zcrmMetaDir, 'profiles');
        await fs.ensureDir(profilesDir);
        for (const profile of profiles) {
          const profileApiName = profile.api_name || profile.name;
          if (profileApiName) {
            await outJson(path.join(profilesDir, `${profileApiName}.profiles-meta.json`), profile, { spaces: 2 });
          }
        }
        if (profiles.length > 0) {
          const removedProfiles = await sweepDir(profilesDir, writtenFiles);
          stats.removedStale += removedProfiles;
        }
        onProgress('FETCH_PROFILES_SUCCESS', 'Profiles retrieved successfully.');
      } catch (err) {
        logError(err, 'CrmMetadataService.extract - Profiles');
        stats.errors.push({ endpoint: '/crm/v8/settings/profiles', error: err.message });
        onProgress('FETCH_PROFILES_WARNING', 'Could not fetch profiles.');
      }

      // 4c. Fetch Roles
      onProgress('FETCH_ROLES', 'Fetching CRM settings roles...');
      try {
        const rolesResponse = await apiClient.get('/crm/v8/settings/roles');
        const roles = rolesResponse.roles || [];
        completeMetadata.roles = roles;
        rolesCount = roles.length;
        const rolesDir = path.join(zcrmMetaDir, 'roles');
        await fs.ensureDir(rolesDir);
        for (const role of roles) {
          const roleApiName = role.api_name || role.name;
          if (roleApiName) {
            await outJson(path.join(rolesDir, `${roleApiName}.roles-meta.json`), role, { spaces: 2 });
          }
        }
        if (roles.length > 0) {
          const removedRoles = await sweepDir(rolesDir, writtenFiles);
          stats.removedStale += removedRoles;
        }
        onProgress('FETCH_ROLES_SUCCESS', 'Roles retrieved successfully.');
      } catch (err) {
        logError(err, 'CrmMetadataService.extract - Roles');
        stats.errors.push({ endpoint: '/crm/v8/settings/roles', error: err.message });
        onProgress('FETCH_ROLES_WARNING', 'Could not fetch roles.');
      }

      // 4d. Fetch Additional Global Settings
      onProgress('FETCH_GLOBAL_SETTINGS', 'Fetching additional global settings...');
      const globalEndpoints = [
        { key: 'inventory_templates', endpoint: '/crm/v8/settings/inventory_templates', label: 'Inventory Templates', detailPath: (item) => `/crm/v8/settings/inventory_templates/${item.id}`, groupBy: (it) => it.module && it.module.api_name, htmlFields: ['content', 'html_content', 'mail_content', 'body'], nameFirst: true },
        { key: 'email_templates', endpoint: '/crm/v8/settings/email_templates', label: 'Email Templates', detailPath: (item) => `/crm/v8/settings/email_templates/${item.id}`, groupBy: (it) => it.module && it.module.api_name, htmlFields: ['mail_content', 'content'], nameFirst: true },
        { key: 'wizards', endpoint: '/crm/v8/settings/wizards', label: 'Wizards', detailPath: (item) => `/crm/v8/settings/wizards/${item.id}${item.layout?.id ? '?layout_id=' + item.layout.id : ''}` },
        { key: 'global_picklists', endpoint: '/crm/v8/settings/global_picklists', label: 'Global Picklists', detailPath: (item) => `/crm/v8/settings/global_picklists/${item.id}` },
        { key: 'rules', metaKey: 'data_sharing_rules', endpoint: '/crm/v8/settings/data_sharing/rules', label: 'Data Sharing Rules', detailPath: (item) => `/crm/v8/settings/data_sharing/rules/${item.id}` },
        { key: 'data_sharing', endpoint: '/crm/v8/settings/data_sharing', label: 'Data Sharing Settings' },
        { key: 'summary', metaKey: 'data_sharing_actions_summary', endpoint: '/crm/v8/settings/data_sharing/rules/actions/summary', label: 'Data Sharing Actions Summary' },
        { key: 'variables', endpoint: '/crm/v8/settings/variables', label: 'Variables', detailPath: (item) => `/crm/v8/settings/variables/${item.id}${item.variable_group?.id ? '?group=' + item.variable_group.id : ''}` },
        { key: 'workflow_rules', endpoint: '/crm/v8/settings/automation/workflow_rules', label: 'Workflow Rules', detailPath: (item) => `/crm/v8/settings/automation/workflow_rules/${item.id}`, groupBy: (it) => (it.trigger_module && (it.trigger_module.api_name || it.trigger_module)) || (it.module && it.module.api_name), jsonExt: '.json', nameFirst: true },
        { key: 'territories', endpoint: '/crm/v8/settings/territories', label: 'Territories', detailPath: (item) => `/crm/v8/settings/territories/${item.id}` }
      ];

      // Writes one global-settings item: places it (optionally) in a subfolder
      // grouped by module, names it, and emits an .html sidecar for templates.
      const writeGlobalItem = async (detailedItem, reqConfig, itemsDir) => {
        if (!detailedItem) return;

        let targetDir = itemsDir;
        if (reqConfig.groupBy) {
          const groupName = sanitizeFileName(reqConfig.groupBy(detailedItem) || '_ungrouped');
          targetDir = path.join(itemsDir, groupName);
          await fs.ensureDir(targetDir);
        }

        const rawBase = reqConfig.nameFirst
          ? (detailedItem.name || detailedItem.api_name || detailedItem.id)
          : (detailedItem.api_name || detailedItem.id || detailedItem.name);
        if (!rawBase) return;
        const base = sanitizeFileName(rawBase);

        const ext = reqConfig.jsonExt || '.meta.json';
        await outJson(path.join(targetDir, `${base}${ext}`), detailedItem, { spaces: 2 });

        // For templates, write the HTML body as a standalone .html file.
        if (reqConfig.htmlFields) {
          const html = pickHtmlContent(detailedItem, reqConfig.htmlFields);
          if (html) await outFile(path.join(targetDir, `${base}.html`), html, 'utf8');
        }
      };

      for (const reqConfig of globalEndpoints) {
        try {
          const response = await apiClient.get(reqConfig.endpoint);
          const items = response[reqConfig.key] || [];
          const outputKey = reqConfig.metaKey || reqConfig.key;
          completeMetadata[outputKey] = items;
          if (items.length > 0) globalSettingsExtracted.push({ key: outputKey, label: reqConfig.label, count: items.length });
          const itemsDir = path.join(zcrmMetaDir, outputKey);
          await fs.ensureDir(itemsDir);

          if (items.length > 0 && reqConfig.detailPath) {
            await mapWithConcurrency(items, concurrency, async (item) => {
              let detailedItem = item;
              if (item.id) {
                try {
                  const detailResponse = await apiClient.get(reqConfig.detailPath(item));
                  detailedItem = (detailResponse[reqConfig.key] && detailResponse[reqConfig.key][0]) ? detailResponse[reqConfig.key][0] : item;
                } catch (detailErr) {
                  detailedItem = item; // fall back to the list item on detail-fetch failure
                }
              }
              await writeGlobalItem(detailedItem, reqConfig, itemsDir);
            });
          } else {
            for (const item of items) {
              await writeGlobalItem(item, reqConfig, itemsDir);
            }
          }

          // Recursive sweep reconciles grouped subfolders too (and prunes empties).
          if (items.length > 0) {
            const removedItems = await sweepDir(itemsDir, writtenFiles);
            stats.removedStale += removedItems;
          }
        } catch (err) {
          handleResourceError(err, reqConfig.endpoint, 'Global', reqConfig.label, true);
          onProgress(`FETCH_${reqConfig.key.toUpperCase()}_WARNING`, `Could not fetch ${reqConfig.label}.`);
        }
      }

      // 5. Retrieve Functions and their Deluge scripts (bounded concurrency)
      onProgress('FETCH_FUNCTIONS', 'Fetching CRM functions...');
      try {
        const functionsResponse = await apiClient.get('/crm/v8/settings/functions');
        completeMetadata.functions = functionsResponse;
        await outJson(path.join(zcrmStoreDir, 'functions.json'), functionsResponse, { spaces: 2 });

        const functionsList = functionsResponse.functions || [];
        functionsCount = functionsList.length;
        await fs.ensureDir(functionsDir);
        await outJson(path.join(functionsDir, 'functions.json'), functionsResponse, { spaces: 2 });

        onProgress('FUNCTIONS_START', `Found ${functionsList.length} functions. Extracting deluge scripts (concurrency: ${concurrency})...`, {
          total: functionsList.length,
          concurrency
        });

        let completedFns = 0;
        await mapWithConcurrency(functionsList, concurrency, async (fn, j) => {
          const fnId = fn.id;
          const fnName = fn.name || `function_${j}`;
          try {
            if (!fnId) return;

            const ns = (fn.nameSpace || getNamespaceForCategory(fn.category)).toLowerCase().trim();
            const fnApiName = fn.api_name || fnName;
            const nsDir = path.join(functionsDir, ns);
            await fs.ensureDir(nsDir);
            const filePath = path.join(nsDir, `${ns}.${fnApiName}.ds`);

            try {
              const scriptContent = await apiClient.get(`/crm/v8/settings/functions/${fnId}/code`);
              if (scriptContent && typeof scriptContent === 'string') {
                const formattedScript = formatDeluge(scriptContent);
                await outFile(filePath, formattedScript, 'utf8');
              } else {
                throw new Error('Empty script code returned');
              }
            } catch (detailErr) {
              stats.errors.push({ endpoint: `/crm/v8/settings/functions/${fnId}/code`, error: detailErr.message });
              logInfo(`Could not fetch details for function ${fnName} (${fnId}): ${detailErr.message}`, 'CrmMetadataService.extract');
              // Write a placeholder so the file is still tracked (and not swept).
              await outFile(filePath, `// Error fetching deluge script for function: ${fnName} (ID: ${fnId})\n// Error: ${detailErr.message}`, 'utf8');
            }
          } catch (fnErr) {
            stats.errors.push({ endpoint: `function:${fnId}`, error: fnErr.message });
            logError(fnErr, `CrmMetadataService.extract - Function: ${fnName}`);
          } finally {
            completedFns++;
            onProgress('FUNCTION_PROGRESS', `[${completedFns}/${functionsList.length}] Extracted: ${fnName}`, {
              completed: completedFns,
              total: functionsList.length,
              name: fnName
            });
          }
        });

        // Remove .ds scripts for functions deleted on Zoho CRM. Only when the
        // functions list came back non-empty, so an empty list never wipes all
        // previously-extracted scripts.
        if (functionsList.length > 0) {
          const removedFns = await sweepDir(functionsDir, writtenFiles);
          stats.removedStale += removedFns;
        }

        onProgress('FETCH_FUNCTIONS_COMPLETE', 'Functions and Deluge scripts extracted successfully.');
      } catch (err) {
        logError(err, 'CrmMetadataService.extract - Functions');
        stats.errors.push({ endpoint: '/crm/v8/settings/functions', error: err.message });
        onProgress('FETCH_FUNCTIONS_WARNING', 'Could not fetch functions list.');

        // Write empty functions placeholder only if none exists yet.
        const fnStorePath = path.join(zcrmStoreDir, 'functions.json');
        if (!(await fs.pathExists(fnStorePath))) {
          await outJson(fnStorePath, { functions: [] }, { spaces: 2 });
        }
      }

      // 6. Generate Master Index
      onProgress('GENERATE_INDEX', 'Generating master index...');
      const indexData = {
        generated_at: new Date().toISOString(),
        crm_org: orgName,
        modules_count: modules.length,
        modules: modules.map(m => ({
          api_name: m.api_name,
          singular_label: m.singular_label,
          plural_label: m.plural_label,
          custom: m.custom
        }))
      };
      await outJson(path.join(zcrmStoreDir, 'index.json'), indexData, { spaces: 2 });

      // 7. Generate Exports under .zcrm/.store/
      onProgress('GENERATE_EXPORTS', 'Creating consolidated export formats...');
      await outJson(path.join(zcrmStoreDir, 'modules_raw.json'), modulesResponse, { spaces: 2 });
      await outJson(path.join(zcrmStoreDir, 'field_map.json'), fieldMap, { spaces: 2 });
      // Layouts rollup for IDE tree views (the VS Code extension reads
      // .zcrm/.store/layouts.json): one flat list, each entry stamped with its
      // module because the per-module layout payloads don't carry it.
      const layoutsRollup = [];
      for (const [moduleApiName, moduleLayouts] of Object.entries(completeMetadata.layouts)) {
        for (const layout of moduleLayouts || []) {
          layoutsRollup.push({
            id: layout.id,
            name: layout.name || layout.display_label,
            api_name: layout.api_name,
            status: layout.status,
            module: (layout.module && layout.module.api_name) ? layout.module : { api_name: moduleApiName }
          });
        }
      }
      await outJson(path.join(zcrmStoreDir, 'layouts.json'), { layouts: layoutsRollup }, { spaces: 2 });
      await outJson(path.join(zcrmStoreDir, 'complete_metadata.json'), completeMetadata);

      // 8. Generate the human-readable result README from the real pulled data.
      onProgress('GENERATE_README', 'Writing result README...');
      try {
        const readme = buildResultReadme({
          orgName,
          generatedAt: indexData.generated_at,
          version: pkg.version,
          dc,
          stats,
          modules: moduleSummaries,
          functionsCount,
          profilesCount,
          rolesCount,
          globalSettings: globalSettingsExtracted
        });
        await outFile(path.join(finalOutputDir, 'README.md'), readme, 'utf8');
      } catch (readmeErr) {
        logInfo(`Could not generate result README: ${readmeErr.message}`, 'CrmMetadataService.extract');
      }

      stats.completedAt = new Date().toISOString();
      stats.crm_org = orgName;
      stats.modulesCount = modules.length;

      onProgress('COMPLETE', 'Metadata extraction completed successfully!', stats);
      return stats;
    } catch (error) {
      logError(error, 'CrmMetadataService.extract - Global Extraction Failure');
      onProgress('FAILURE', `Extraction failed: ${error.message}`);
      throw error;
    } finally {
      // Release the cross-process sync lock; a failure to remove it only costs
      // the next run a stale-lock reclaim after LOCK_STALE_MS.
      try { await fs.remove(lockPath); } catch (unlockErr) { logInfo(`Could not remove sync lock: ${unlockErr.message}`, 'CrmMetadataService.extract'); }
      // Stop mirroring logs to the result folder once the pull is done (the
      // CLI's own per-command debug log stays active).
      if (outputLogPath) removeSessionLog(outputLogPath);
    }
  }
}

module.exports = new CrmMetadataService();

// Exposed for reuse by functionService (`fn pull`/`fn test`) so a single
// function lands in the exact same `crm/functions/<namespace>/` path the full
// `pull` uses. Purely additive — `extract()` still calls the module-scope
// function directly, so `pull` behavior is unchanged.
module.exports.getNamespaceForCategory = getNamespaceForCategory;
