/**
 * Runs an async worker over a list of items with a bounded number of items
 * "in progress" at any time, preserving result order. This caps how many
 * worker invocations are active simultaneously — useful for respecting Zoho
 * CRM's per-org concurrency limit while still parallelizing independent work.
 *
 * The worker is expected to handle its own errors; if a worker rejects, the
 * whole operation rejects (so wrap per-item logic in try/catch when partial
 * failure should be tolerated).
 *
 * @template T, R
 * @param {T[]} items - The items to process.
 * @param {number} limit - Maximum concurrent worker invocations (>= 1).
 * @param {(item: T, index: number) => Promise<R>} worker - Async worker.
 * @returns {Promise<R[]>} Results in the same order as `items`.
 */
async function mapWithConcurrency(items, limit, worker) {
  const results = new Array(items.length);
  const max = Math.max(1, Math.min(parseInt(limit, 10) || 1, items.length || 1));
  let nextIndex = 0;

  async function runner() {
    while (true) {
      const i = nextIndex++;
      if (i >= items.length) return;
      results[i] = await worker(items[i], i);
    }
  }

  const runners = [];
  for (let k = 0; k < max; k++) {
    runners.push(runner());
  }
  await Promise.all(runners);
  return results;
}

module.exports = { mapWithConcurrency };
